from pysat.solvers import Glucose3

n = 7
def var(i, j, k):
    return i * n * n + j * n + k + 1

solver = Glucose3()

# Exactly one k for each i, j
for i in range(n):
    for j in range(n):
        solver.add_clause([var(i, j, k) for k in range(n)])
        for k1 in range(n):
            for k2 in range(k1 + 1, n):
                solver.add_clause([-var(i, j, k1), -var(i, j, k2)])

# Exactly one j for each i, k
for i in range(n):
    for k in range(n):
        solver.add_clause([var(i, j, k) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                solver.add_clause([-var(i, j1, k), -var(i, j2, k)])

# Exactly one i for each j, k
for j in range(n):
    for k in range(n):
        solver.add_clause([var(i, j, k) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                solver.add_clause([-var(i1, j, k), -var(i2, j, k)])

# Idempotent
for i in range(n):
    solver.add_clause([var(i, i, i)])

# QG3: x[i][j] = u and x[j][i] = v implies x[u][v] = i
for i in range(n):
    for j in range(n):
        for u in range(n):
            for v in range(n):
                solver.add_clause([-var(i, j, u), -var(j, i, v), var(u, v, i)])

if solver.solve():
    model = solver.get_model()
    res = []
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if model[var(i, j, k) - 1] > 0:
                    res.append(k)
    print(res)
else:
    print("UNSAT")

